import sys

def lcs_length(s1: str, s2: str) -> int:
    if not s1 or not s2:
        return 0
    if len(s1) > len(s2):
        s1, s2 = s2, s1
    # Bit-parallel LCS (Allison-Dix / Hyyrö algorithm)
    masks = {}
    for i, ch in enumerate(s1):
        masks[ch] = masks.get(ch, 0) | (1 << i)

    S = (1 << len(s1)) - 1
    mask_all = S
    get = masks.get
    for ch in s2:
        PM = get(ch, 0)
        u = S & PM
        S = (S + u) | (S - u)
    # Count 0 bits in lowest len(s1) bits of S
    return len(s1) - (S & mask_all).bit_count()

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        s1 = lines[0] if lines else ""
        s2 = ""
    else:
        s1, s2 = lines[0], lines[1]
    print(lcs_length(s1, s2))

if __name__ == "__main__":
    main()

