int lcs_ascii(const uint8_t *s1, int m, const uint8_t *s2, int n) {
    if (m == 0 || n == 0) return 0;

    // Trim common prefix
    int start = 0;
    int min_len = m < n ? m : n;
    while (start < min_len && s1[start] == s2[start]) {
        start++;
    }
    s1 += start;
    s2 += start;
    m -= start;
    n -= start;

    // Trim common suffix
    while (m > 0 && n > 0 && s1[m - 1] == s2[n - 1]) {
        m--;
        n--;
    }

    if (m == 0 || n == 0) return start;

    if (m > n) {
        const uint8_t *tmp_s = s1; s1 = s2; s2 = tmp_s;
        int tmp_l = m; m = n; n = tmp_l;
    }

    int words = (m + 63) >> 6;

    // Fast path for m <= 3200 (words <= 50) using stack allocation
    uint64_t stack_pm[256 * 50];
    uint64_t stack_S[50];
    uint64_t *pm = (words <= 50) ? stack_pm : (uint64_t *)calloc(256 * words, sizeof(uint64_t));
    uint64_t *S = (words <= 50) ? stack_S : (uint64_t *)malloc(words * sizeof(uint64_t));

    if (words <= 50) {
        memset(pm, 0, 256 * words * sizeof(uint64_t));
    }

    for (int i = 0; i < m; i++) {
        pm[(size_t)s1[i] * words + (i >> 6)] |= (1ULL << (i & 63));
    }

    for (int w = 0; w < words; w++) {
        S[w] = ~0ULL;
    }

    for (int j = 0; j < n; j++) {
        const uint64_t *pm_c = pm + (size_t)s2[j] * words;
        unsigned long long carry = 0;
        for (int w = 0; w < words; w++) {
            unsigned long long sw = S[w];
            unsigned long long u = sw & pm_c[w];
            unsigned long long sum = __builtin_addcll(sw, u, carry, &carry);
            S[w] = sum | (sw - u);
        }
    }

    if (m & 63) {
        S[words - 1] |= (~0ULL << (m & 63));
    }

    int zeros = 0;
    for (int w = 0; w < words; w++) {
        zeros += __builtin_popcountll(~S[w]);
    }

    if (words > 50) {
        free(pm);
        free(S);
    }

    return start + zeros;
